def _check_tier(tier, label):
    previous_end = None
    for start, end, _ in tier:
        if end <= start:
            raise ValueError(f"{label}: interval [{start}, {end}] is not positive length")
        if previous_end is not None and start < previous_end:
            raise ValueError(f"{label}: intervals overlap or are out of order at {start}")
        previous_end = end


def phone_durations(words, phones):
    _check_tier(words, "words")
    _check_tier(phones, "phones")
    spoken = [(s, e, t) for s, e, t in words if t]
    out = [{"word": t, "start": s, "end": e, "phones": []} for s, e, t in spoken]
    for start, end, text in phones:
        if not text:
            continue
        owners = [i for i, (s, e, _) in enumerate(spoken) if s <= start and end <= e]
        if len(owners) != 1:
            raise ValueError(
                f"phone {text!r} at [{start}, {end}] is not inside exactly one word"
            )
        out[owners[0]]["phones"].append((text, end - start))
    return out
